WITH valid AS (SELECT id, customer_id, start_date, end_date, status, CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END is_cancelled, CASE WHEN monthly_fee >= 269 THEN 'High' WHEN monthly_fee >= 117 THEN 'Medium' ELSE 'Low' END monthly_fee_level FROM subscriptions WHERE start_date > DATE '2024-03-10' AND customer_id IS NOT NULL AND plan IN ('enterprise', 'basic', 'premium')) SELECT id, customer_id, start_date, end_date, status, is_cancelled, monthly_fee_level, SUM(is_cancelled) OVER (PARTITION BY status ORDER BY is_cancelled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_is_cancelled, SUM(is_cancelled) OVER (ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_is_cancelled, LAST_VALUE(is_cancelled) IGNORE NULLS OVER (PARTITION BY status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_is_cancelled, NTILE(5) OVER (PARTITION BY status ORDER BY is_cancelled DESC, id) is_cancelled_bucket FROM valid
